// Virtual Office - 2D Visualization
const canvas = document.getElementById('officeCanvas');
// `ctx` is swapped to an offscreen context while the static layer is drawn.
var ctx = canvas.getContext('2d');

// Device pixel ratio for the canvas bitmap: re-read on every resize, capped at
// 2 (a 3x phone would otherwise paint 9x the pixels for no visible gain).
const VO_MAX_DPR = 2;
// Sharp pixels (Q-03): the backing store follows the real device pixel ratio
// (phones at 2.625 / 3 / 3.5), so a whole number of device pixels per art pixel
// is possible there; "Fill the screen" keeps the v0.9 cap.
const VO_MAX_DPR_SHARP = 4;
var DPR = Math.max(1, Math.min(VO_MAX_DPR, Number(window.devicePixelRatio) || 1));
// Debug overlays (fps box, [perf] console lines) only with ?debug=1 or
// localStorage 'vo-debug' = '1'.
var VO_DEBUG = (function() {
    try {
        return /(?:^|[?&])debug=1(?:&|$)/.test(window.location.search || '') || window.localStorage.getItem('vo-debug') === '1';
    } catch (e) { return false; }
})();
const TILE = 40;
const HALF_TILE = TILE / 2;

// --- DYNAMIC CANVAS SIZE (data-driven) ---
const OFFICE_CONFIG_KEY = 'vo-product-office-config';
const COLOR_FAVORITES_KEY = 'vo-product-color-favorites';
const MIN_TILES_X = 10;
const MIN_TILES_Y = 10;

// Load office config: server first, then localStorage fallback
function loadOfficeConfig() {
    // Try localStorage first for immediate startup (sync)
    try {
        const saved = localStorage.getItem(OFFICE_CONFIG_KEY);
        if (saved) return JSON.parse(saved);
    } catch (e) {}
    return { canvasWidth: 1000, canvasHeight: 700 };
}

// Async: fetch server config and apply if newer/exists
var _serverConfigLoaded = false;
var _serverConfigAttempts = 0;
var _officeEditedOffline = false;
var _officeBootJson = '';
function _loadServerConfig() {
    _serverConfigAttempts++;
    var rev = null;
    fetch('/api/office-config', { cache: 'no-store' }).then(function(r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        rev = r.headers.get('X-VO-Rev');
        return r.json();
    }).then(function(data) {
        if (!data || typeof data !== 'object' || data.error) throw new Error((data && data.error) || 'empty office config');
        _serverConfigLoaded = true;
        if (_officeEditedOffline && _officeBootJson && window.VOSave) {
            // Edits made before the server answered (v0.10.1 saves): merge them onto its
            // copy (base = the layout this window started from) and save, never drop them.
            _serverConfigWarned = false;
            _officeEditedOffline = false;
            _officeBase = _normalizeServerOfficeConfig(JSON.parse(_officeBootJson));
            _lastSavedOfficeJson = JSON.stringify(_normalizeServerOfficeConfig(data));
            _mergeOfficeConflict(data, rev, 'Connected to the office server again. Your changes are kept and saved.');
            saveOfficeConfig();
            return;
        }
        if (_serverConfigWarned) { _serverConfigWarned = false; _voConfigToast('Connected to the office server again. The office is up to date.', 'success'); }
        if (typeof _invalidateBranchCache === 'function') _invalidateBranchCache();
        // Merge server config into officeConfig
        if (data.canvasWidth) { W = data.canvasWidth; officeConfig.canvasWidth = W; }
        if (data.canvasHeight) { H = data.canvasHeight; officeConfig.canvasHeight = H; }
        if (data.walls) officeConfig.walls = data.walls;
        if (data.floor) officeConfig.floor = data.floor;
        if (data.furniture) officeConfig.furniture = _migrateLegacyFurniture(data.furniture);
        if (data.agents) officeConfig.agents = data.agents;
        if (data.branches) officeConfig.branches = data.branches;
        if (data.pet) officeConfig.pet = data.pet;
        // Migration: add default interactive windows if none exist
        if (officeConfig.furniture && !officeConfig.furniture.some(function(f){ return f.type === 'interactiveWindow'; })) {
            officeConfig.furniture.push({ id: 'iw-hq-left',  type: 'interactiveWindow', x: 388, y: 10, weather: true, showSun: true });
            officeConfig.furniture.push({ id: 'iw-hq-right', type: 'interactiveWindow', x: 576, y: 10, weather: true, showSun: false });
        }
        // Trigger proper canvas resize (reads wrapper dimensions, applies DPR)
        // and re-apply the camera view for the (possibly new) office size.
        if (typeof resizeCanvas === 'function') resizeCanvas(true);
        if (typeof _refreshWallSectionButtons === 'function') _refreshWallSectionButtons();
        // Re-apply agent overrides
        if (typeof _initAgentsFromDefs === 'function' && _rosterLoaded) _initAgentsFromDefs();
        if (typeof _syncAllDeskAssignments === 'function') _syncAllDeskAssignments();
        if (typeof getInteractionSpots === 'function') getInteractionSpots();
        if (typeof buildCollisionGrid === 'function') buildCollisionGrid();
        if (typeof initPets === 'function') initPets();
        // Cache locally; this is also the "already saved" baseline.
        officeConfig.canvasWidth = W;
        officeConfig.canvasHeight = H;
        _lastSavedOfficeJson = JSON.stringify(officeConfig);
        // The revision this window is based on, and the layout as read (merge base after a 409).
        _officeRev = rev;
        _officeBase = JSON.parse(_lastSavedOfficeJson);
        try { localStorage.setItem(OFFICE_CONFIG_KEY, _lastSavedOfficeJson); } catch (e) {}
        if (typeof _markSceneDirty === 'function') _markSceneDirty();
        if (typeof _invalidateStaticLayer === 'function') _invalidateStaticLayer();
    }).catch(function(e) {
        // Server not reachable yet: keep the cached copy on screen, keep saving
        // blocked (CV-20) and try again with a gentle backoff.
        var delay = Math.min(30000, 2000 * _serverConfigAttempts);
        setTimeout(_loadServerConfig, delay);
        // Say so once (UI-18), and say again when it comes back.
        if (!_serverConfigWarned) {
            _serverConfigWarned = true;
            var cached = false;
            try { cached = !!localStorage.getItem(OFFICE_CONFIG_KEY); } catch (err) {}
            _voConfigToast(cached ? 'Cannot reach the office server. Showing the last saved layout; changes are saved when it is back.'
                : 'Cannot reach the office server. Showing the default layout until it is back.', 'warning');
        }
    });
}
var _serverConfigWarned = false;
// Toasts may be asked for before ui-modern.js has loaded: wait for it a little, never block with alert().
function _voConfigToast(message, kind, tries) {
    if (window.VOUI && typeof window.VOUI.toast === 'function') {
        try { window.VOUI.toast(message, { kind: kind || 'info' }); } catch (e) {}
        return;
    }
    if ((tries || 0) < 40) setTimeout(function() { _voConfigToast(message, kind, (tries || 0) + 1); }, 250);
}

// Save office config to BOTH server and localStorage.
// Returns a Promise<boolean> (true = the server stored it). The server copy is
// never written before it has been loaded once, so a partial local fallback
// can not wipe agents, the pet or branches (CV-20). The result is shown to
// the user as Saving / Saved / Save failed (CV-08).
var _officeSaveState = { state: 'idle', detail: '' };
var _lastSavedOfficeJson = '';
function _setOfficeSaveState(state, detail) {
    _officeSaveState = { state: state, detail: detail || '' };
    try { window.dispatchEvent(new CustomEvent('vo:office-save', { detail: _officeSaveState })); } catch (e) {}
    if (typeof _renderOfficeSaveStatus === 'function') _renderOfficeSaveStatus();
}
function saveOfficeConfig() {
    officeConfig.canvasWidth = W;
    officeConfig.canvasHeight = H;
    _deskPosCache = null; // invalidate lamp cache
    MEETING_SLOTS = getMeetingSlots(); // re-derive meeting slots from current meeting table position
    // Sync LOCATIONS.meeting with actual meeting table position
    var mtPos = getMeetingTablePos();
    if (mtPos) { LOCATIONS.meeting.x = mtPos.x; LOCATIONS.meeting.y = mtPos.y; }
    if (typeof _invalidateStaticLayer === 'function') _invalidateStaticLayer();
    if (typeof buildCollisionGrid === 'function') buildCollisionGrid();
    var currentJson = JSON.stringify(officeConfig);
    // A gesture that changed nothing (plain click) leaves no undo step behind.
    if (typeof _undoStack !== 'undefined' && _undoStack.length && _undoStack[_undoStack.length - 1] === currentJson) {
        _undoStack.pop();
        if (typeof _updateSaveUndoButtons === 'function') _updateSaveUndoButtons();
    }
    var queue = _officeQueue();
    if (currentJson === _lastSavedOfficeJson && _officeSaveState.state !== 'failed' && !(queue && queue.pending())) return Promise.resolve(true);
    if (!_serverConfigLoaded) {
        _officeEditedOffline = true; // merged and saved when the server answers
        _setOfficeSaveState('failed', 'The office has not loaded from the server yet; your change is saved when it does.');
        return Promise.resolve(false);
    }
    // Save to localStorage immediately (fast)
    try { localStorage.setItem(OFFICE_CONFIG_KEY, JSON.stringify(officeConfig)); } catch (e) {}
    _setOfficeSaveState('saving');
    // One save at a time (v0.10.1 saves): rapid edits coalesce into the latest
    // layout, an older copy never goes out after a newer one, failures retry.
    if (!queue) return _sendOfficeConfig({ seq: ++_officeSaveSeqFallback }).then(function(r) {
        _setOfficeSaveState(r.ok ? 'saved' : 'failed', r.error);
        return !!r.ok;
    });
    return queue.request(500);
}
function _flushOfficeConfigSave(keepalive) {
    var queue = _officeQueue();
    if (queue) queue.flush(keepalive);
}

// Save queue + revision of the saved layout (v0.10.1 saves). The server answers
// 409 when the layout changed since this window read it (another tab, an agent
// or the agent settings); this window then merges both changes and saves again.
var _officeRev = null;
var _officeBase = null;
var _officeAckSeq = 0;
var _officeConflicts = 0;
var _officeSaveSeqFallback = 0;
var _officeSaveQueue = null;
var _officeSaveClient = Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
function _officeQueue() {
    if (!_officeSaveQueue && typeof window !== 'undefined' && window.VOSave) {
        _officeSaveQueue = window.VOSave.queue({
            send: _sendOfficeConfig,
            onState: function(state, detail) { _setOfficeSaveState(state, detail); }
        });
    }
    return _officeSaveQueue;
}
function _sendOfficeConfig(ctx) {
    var body = JSON.stringify(officeConfig);
    var status = 0;
    var headers = { 'Content-Type': 'application/json', 'X-VO-Client': _officeSaveClient, 'X-VO-Save-Seq': String(ctx.seq) };
    if (_officeRev) headers['X-VO-Base-Rev'] = _officeRev;
    var opts = { method: 'POST', headers: headers, body: body };
    if (ctx.keepalive && body.length < 60000) opts.keepalive = true; // survives the tab closing
    return fetch('/api/office-config', opts).then(function(res) {
        status = res.status;
        var rev = res.headers.get('X-VO-Rev');
        return res.json().catch(function() { return {}; }).then(function(data) {
            if (res.ok && !(data && data.error)) {
                if (ctx.seq > _officeAckSeq) {
                    _officeAckSeq = ctx.seq;
                    _officeRev = data.rev || rev || _officeRev;
                    _officeBase = JSON.parse(body);
                    _lastSavedOfficeJson = body;
                }
                _officeConflicts = 0;
                return { ok: true };
            }
            // A newer save from this window is already stored: nothing is lost.
            if (status === 409 && data && data.error === 'stale_save') return { ok: true };
            if (status === 409 && data && data.error === 'conflict' && !ctx.overlap) {
                _mergeOfficeConflict(data.config, data.rev || rev);
                if (++_officeConflicts <= 5) return { ok: false, again: true };
            }
            throw new Error((data && (data.message || data.error)) || ('HTTP ' + status));
        });
    }).catch(function(e) {
        console.warn('Failed to save the office to the server:', e);
        return { ok: false, retry: !status || status >= 500 || status === 408 || status === 409 || status === 429,
            error: _friendlySaveError(e, status) };
    });
}
// Layout from the server, migrated like the loader does (so a 409 merge only
// sees real changes, not migrations).
function _normalizeServerOfficeConfig(data) {
    var out = JSON.parse(JSON.stringify(data));
    if (out.furniture) out.furniture = _migrateLegacyFurniture(out.furniture);
    if (out.furniture && !out.furniture.some(function(f) { return f.type === 'interactiveWindow'; })) {
        out.furniture.push({ id: 'iw-hq-left',  type: 'interactiveWindow', x: 388, y: 10, weather: true, showSun: true });
        out.furniture.push({ id: 'iw-hq-right', type: 'interactiveWindow', x: 576, y: 10, weather: true, showSun: false });
    }
    return out;
}
function _mergeOfficeConflict(remoteRaw, rev, message) {
    _officeRev = rev || _officeRev;
    if (!remoteRaw || typeof remoteRaw !== 'object' || !window.VOSave) return; // nothing to merge with: ours goes out
    var remote = _normalizeServerOfficeConfig(remoteRaw);
    var base = _officeBase || {};
    var local = JSON.parse(JSON.stringify(officeConfig));
    // Keys the server copy does not have are this window's (never a deletion there).
    Object.keys(local).forEach(function(k) { if (!(k in remote)) remote[k] = (k in base) ? base[k] : local[k]; });
    var merged = window.VOSave.merge3(base, local, remote);
    _officeBase = remote;
    var wallsBefore = JSON.stringify((officeConfig.walls || {}).interior || []);
    var sizeBefore = W + 'x' + H;
    Object.keys(officeConfig).forEach(function(k) { if (!(k in merged)) delete officeConfig[k]; });
    Object.keys(merged).forEach(function(k) { officeConfig[k] = merged[k]; });
    if (officeConfig.canvasWidth) W = officeConfig.canvasWidth;
    if (officeConfig.canvasHeight) H = officeConfig.canvasHeight;
    // Wall selection is by index: drop it when the wall list changed under it.
    if (JSON.stringify((officeConfig.walls || {}).interior || []) !== wallsBefore) { selectedWallIdx = null; _multiSelectedWalls = []; }
    if (typeof _invalidateBranchCache === 'function') _invalidateBranchCache();
    if (sizeBefore !== W + 'x' + H && typeof resizeCanvas === 'function') resizeCanvas(true);
    if (typeof _refreshWallSectionButtons === 'function') _refreshWallSectionButtons();
    if (typeof _initAgentsFromDefs === 'function' && _rosterLoaded) _initAgentsFromDefs();
    if (typeof _syncAllDeskAssignments === 'function') _syncAllDeskAssignments();
    if (typeof getInteractionSpots === 'function') getInteractionSpots();
    if (typeof buildCollisionGrid === 'function') buildCollisionGrid();
    if (typeof _markSceneDirty === 'function') _markSceneDirty();
    if (typeof _invalidateStaticLayer === 'function') _invalidateStaticLayer();
    if (window.OfficeLayouts && window.OfficeLayouts.refreshSelection) window.OfficeLayouts.refreshSelection();
    try { localStorage.setItem(OFFICE_CONFIG_KEY, JSON.stringify(officeConfig)); } catch (e) {}
    // Only a real change from elsewhere is news: when the server copy held nothing this window
    // does not already have, the merge is silent.
    if (message || !window.VOSave.same(merged, local)) {
        _voConfigToast(message || 'The office was also changed somewhere else. Both changes are kept.', 'info');
    }
}

// Plain words for a failed save (OE-23); the edit itself stays in this tab.
function _friendlySaveError(e, status) {
    var msg = String((e && e.message) || '');
    if (!status) return 'Could not reach the office server. Your changes are kept here.';
    if (status === 401 || status === 403) return 'You are signed out or not allowed to edit. Sign in again, then retry.';
    if (status === 413) return 'The office is too big to save.';
    if (status >= 500) return 'The office server had a problem saving. Your changes are kept here.';
    if (msg && !/^HTTP \d+$/.test(msg)) return msg;
    return 'The office server refused the save (' + status + ').';
}

// Never lose an edit to a closed tab (OE-02): a save still waiting for its
// debounce goes out at once (keepalive), and the browser asks before leaving
// while a save is pending or has failed.
window.addEventListener('beforeunload', function(e) {
    _flushOfficeConfigSave(true);
    var st = _officeSaveState && _officeSaveState.state;
    if (st === 'saving' || st === 'failed') {
        e.preventDefault();
        e.returnValue = '';
        return '';
    }
});
// Phones close tabs without beforeunload: send what is pending when the page hides.
window.addEventListener('pagehide', function() { _flushOfficeConfigSave(true); });
document.addEventListener('visibilitychange', function() { if (document.visibilityState === 'hidden') _flushOfficeConfigSave(true); });

function loadColorFavorites() {
    try {
        const saved = localStorage.getItem(COLOR_FAVORITES_KEY);
        if (saved) {
            const parsed = JSON.parse(saved);
            if (Array.isArray(parsed) && parsed.length) return parsed;
        }
    } catch (e) {}
    return ['#ffffff', '#e3f2fd', '#90caf9', '#546e7a', '#37474f', '#263238', '#ffd600', '#ffca28'];
}

function saveColorFavorites() {
    try {
        localStorage.setItem(COLOR_FAVORITES_KEY, JSON.stringify(colorFavorites));
    } catch (e) {}
}

const _officeConfig = loadOfficeConfig();
var colorFavorites = loadColorFavorites();
var W = _officeConfig.canvasWidth;
var H = _officeConfig.canvasHeight;

const DEFAULT_BRANCHES = [
    { id: 'HQ', name: 'Office Manager', emoji: '⚡', theme: 'branch-gold' },
    { id: 'PQ', name: 'Operations', emoji: '🔧', theme: 'branch-blue' },
    { id: 'ENG', name: 'Engineering', emoji: '🏗️', theme: 'branch-orange' },
    { id: 'GEN', name: 'General Office', emoji: '🌐', theme: 'branch-cyan' },
    { id: 'BIZ', name: 'Business', emoji: '🔥', theme: 'branch-red' }
];
const UNASSIGNED_BRANCH = { id: 'UNASSIGNED', name: 'Unassigned', emoji: '', theme: 'branch-gray' };

var _branchListCache = null;
var _branchMapCache = null;
var _branchCacheKey = '';
function _invalidateBranchCache() { _branchListCache = null; _branchMapCache = null; _branchCacheKey = ''; }
function getBranchList() {
    var src = (officeConfig && officeConfig.branches) || _officeConfig.branches || DEFAULT_BRANCHES;
    // Key on every id + name so edits, renames and imports invalidate it (CV-20).
    var key = src.map(function(b) { return (b && b.id) + '\u0001' + (b && b.name) + '\u0001' + (b && b.color || '') + '\u0001' + (b && b.emoji || ''); }).join('\u0002');
    if (_branchListCache && _branchCacheKey === key) return _branchListCache;
    var list = src.slice();
    var hasUnassigned = list.some(function(b){ return b.id === UNASSIGNED_BRANCH.id; });
    if (!hasUnassigned) list.push(UNASSIGNED_BRANCH);
    _branchListCache = list;
    _branchCacheKey = key;
    // Build lookup map
    _branchMapCache = {};
    list.forEach(function(b) { _branchMapCache[b.id] = b; });
    return list;
}
function getBranchById(branchId) {
    if (!_branchMapCache) getBranchList();
    return (_branchMapCache && _branchMapCache[branchId]) || UNASSIGNED_BRANCH;
}
function getBranchDisplayName(branchId) {
    return getBranchById(branchId).name;
}
function getBranchTheme(branchId) {
    return getBranchById(branchId).theme || 'branch-gray';
}
function ensureValidAgentBranches() {
    var valid = new Set(getBranchList().map(function(b){ return b.id; }));
    agents.forEach(function(a){ if (!valid.has(a.branch)) a.branch = 'UNASSIGNED'; });
    if (officeConfig.agents) {
        officeConfig.agents.forEach(function(a){ if (!valid.has(a.branch)) a.branch = 'UNASSIGNED'; });
    }
}

// --- OFFICE CONFIG (data-driven) ---
var officeConfig = {
    canvasWidth: W,
    canvasHeight: H,
    walls: _officeConfig.walls || {
        topWall: { color: '#37474f', accentColor: '#263238', trimColor: '#fff' },
        sections: [
            { x: 0,   w: 380, color: '#37474f', accentColor: '#263238' }
        ],
        height: 90,
        trimColor: '#fff'
    },
    floor: _officeConfig.floor || { color1: '#c0c0c0', color2: '#b0b0b0' },
    furniture: _officeConfig.furniture || [],  // populated by initOfficeConfig() if empty
    branches: _officeConfig.branches || DEFAULT_BRANCHES.slice()
};

function getTopWallConfig() {
    var walls = (officeConfig && officeConfig.walls) || {};
    var topWall = walls.topWall || {};
    var sections = Array.isArray(walls.sections) ? walls.sections : [];
    if (!topWall.color && sections[0]) topWall.color = sections[0].color;
    if (!topWall.accentColor && sections[0]) topWall.accentColor = sections[0].accentColor;
    if (!topWall.trimColor) topWall.trimColor = walls.trimColor || '#fff';
    if (!topWall.color) topWall.color = '#37474f';
    if (!topWall.accentColor) topWall.accentColor = '#263238';
    return topWall;
}

function getRenderedWallSections() {
    var topWall = getTopWallConfig();
    return [{
        x: 0,
        w: W,
        color: topWall.color,
        accentColor: topWall.accentColor,
        trimColor: topWall.trimColor,
        sourceIndex: 0
    }];
}

// --- EDIT MODE STATE ---
var editMode = false;
var editHoverTile = null; // {tx, ty} tile coords under mouse
// Floor painter (OE-10, contract C2): `active` = the next drag paints a zone of
// floor (tile units) with the chosen preset; `whole` = clicks repaint the base floor.
var _floorPaint = { active: false, preset: null, start: null, end: null };
// Wall paint bucket: while on, a click on a wall paints it with the chosen colours.
var _wallPaint = { active: false, colors: null };

// --- MULTI-SELECT (marquee) ---
var _multiSelected = []; // array of furniture ids
var _multiSelectedWalls = []; // array of indexes in officeConfig.walls.interior
var _marqueeStart = null; // {x, y} world coords
var _marqueeEnd = null;
var _multiDragging = false;
var _multiDragStart = null; // {x, y}

// --- SNAP (whole tile / half tile / free) ---
// One rule for the ghost, the click and dragging: the item's footprint is
// centred on the pointer, then snapped to the grid. Alt (Option) = free while
// held. A click always places exactly what the ghost shows (OE-01, OE-11).
const EDIT_SNAP_MODES = {
    tile: { step: TILE,      label: 'Whole tile' },
    half: { step: HALF_TILE, label: 'Half tile' },
    free: { step: 1,         label: 'Free' },
};
var editSnapMode = (function() {
    try { var saved = localStorage.getItem('vo-editor-snap'); if (saved && EDIT_SNAP_MODES[saved]) return saved; } catch (e) {}
    return 'tile';
})();
var _editAltSnap = false; // Alt held: free placement for this gesture
function _editSnapStep() {
    return _editAltSnap ? 1 : (EDIT_SNAP_MODES[editSnapMode] || EDIT_SNAP_MODES.tile).step;
}
function setEditSnapMode(mode) {
    if (!EDIT_SNAP_MODES[mode]) return;
    editSnapMode = mode;
    try { localStorage.setItem('vo-editor-snap', mode); } catch (e) {}
    try { window.dispatchEvent(new CustomEvent('vo:editor-snap', { detail: { mode: mode } })); } catch (e) {}
}
// Snap one axis: centre a span of whole grid cells on the pointer, then centre
// the item inside that span (so a 2-tile desk fills exactly 2 tiles).
function _snapAxis(center, size, step) {
    if (step <= 1) return Math.round(center - size / 2);
    var cells = Math.max(1, Math.ceil(size / step - 1e-6));
    var span = cells * step;
    var start = Math.round((center - span / 2) / step) * step;
    return Math.round(start + (span - size) / 2);
}
// Draw position (item.x/y) for an item of `type` (and rotation) whose
// footprint should sit under the world point, using the current snap step.
function _snapItemToPoint(type, worldX, worldY, rotation) {
    var probe = { type: type, x: 0, y: 0, rotation: rotation || 0 };
    var r = _getItemWorldRect(probe); // footprint relative to a (0,0) origin
    var step = _editSnapStep();
    var left = _snapAxis(worldX, r.w, step);
    var top = _snapAxis(worldY, r.h, step);
    // Whole pixels for the draw position (crisp art); bounds checks allow the
    // sub-pixel difference this leaves between footprint and grid.
    return { x: Math.round(left - r.x), y: Math.round(top - r.y) };
}
// Snap a dragged item whose draw position would be (rawX, rawY): its
// footprint snaps like a placed one; free mode keeps whole pixels.
function _snapDraggedItem(item, rawX, rawY) {
    var r = _getItemWorldRect({ type: _mk(item), x: rawX, y: rawY, rotation: item.rotation || 0 });
    var pos = _snapItemToPoint(_mk(item), r.x + r.w / 2, r.y + r.h / 2, item.rotation || 0);
    return pos;
}

// --- UNDO / SAVE SYSTEM ---
// One commit model (CV-08 / U8): every finished edit (drag end, add, delete,
// rotate, colour, resize, Undo, Redo) is saved right away and the toolbar
// shows Saving / All changes saved / Save failed. A click that changes
// nothing records nothing and posts nothing.
var _undoStack = [];
var _redoStack = [];
var _hasUnsavedChanges = false;
const MAX_UNDO = 30;

// Snapshot the layout before a change. Duplicate snapshots are dropped, and a
// snapshot that turns out to equal the saved state is discarded on commit.
function _pushUndo() {
    var snap = JSON.stringify(officeConfig);
    if (_undoStack.length && _undoStack[_undoStack.length - 1] === snap) return;
    _undoStack.push(snap);
    if (_undoStack.length > MAX_UNDO) _undoStack.shift();
    _redoStack = [];
    _updateSaveUndoButtons();
}

// Put a JSON snapshot of officeConfig back on screen (Undo, Redo, Cancel).
function applyOfficeConfigSnapshot(snapshot) {
    var prev = typeof snapshot === 'string' ? JSON.parse(snapshot) : snapshot;
    if (!prev || typeof prev !== 'object') return false;
    officeConfig.walls = prev.walls || officeConfig.walls;
    officeConfig.floor = prev.floor || officeConfig.floor;
    officeConfig.furniture = Array.isArray(prev.furniture) ? _migrateLegacyFurniture(prev.furniture) : officeConfig.furniture;
    if (prev.branches) officeConfig.branches = prev.branches;
    W = Number(prev.canvasWidth) || W;
    H = Number(prev.canvasHeight) || H;
    officeConfig.canvasWidth = W;
    officeConfig.canvasHeight = H;
    if (!officeConfig.walls.interior) officeConfig.walls.interior = [];
    getInteractionSpots();
    buildCollisionGrid();
    _syncAllDeskAssignments();
    if (typeof _invalidateBranchCache === 'function') _invalidateBranchCache();
    if (typeof _refreshWallSectionButtons === 'function') _refreshWallSectionButtons();
    selectedItemId = null;
    selectedWallIdx = null;
    _multiSelected = [];
    _multiSelectedWalls = [];
    _marqueeStart = null;
    _marqueeEnd = null;
    _marqueeMode = false;
    if (_floatingToolbar) _floatingToolbar.style.display = 'none';
    if (typeof _hideColorPicker === 'function') _hideColorPicker();
    if (typeof resizeCanvas === 'function') resizeCanvas(true);
    _invalidateStaticLayer();
    return true;
}

// v0.13 cancel: what Cancel would put back (the parts applyOfficeConfigSnapshot restores: walls,
// floor, furniture, branches, office size) as one canonical string. Key order, float noise,
// null/undefined keys, rotation 0 and a default variant id ('classic', the type's first row) do
// not count, so "is there anything to discard?" is a plain compare. Agents and pet settings are
// not part of the layout (Cancel never restores them) and are left out.
function _canonLayoutValue(v) {
    if (typeof v === 'number') return isFinite(v) ? Math.round(v * 1000) / 1000 : 0;
    if (Array.isArray(v)) return v.map(_canonLayoutValue);
    if (v && typeof v === 'object') {
        var o = {};
        Object.keys(v).sort().forEach(function(k) {
            if (v[k] === undefined || v[k] === null) return;
            o[k] = _canonLayoutValue(v[k]);
        });
        return o;
    }
    return v;
}
function officeLayoutKey(cfg) {
    if (typeof cfg === 'string') { try { cfg = JSON.parse(cfg); } catch (e) { return String(cfg); } }
    if (!cfg || typeof cfg !== 'object') return '';
    var furniture = (Array.isArray(cfg.furniture) ? cfg.furniture : []).map(function(f) {
        if (!f || typeof f !== 'object') return f;
        var c = Object.assign({}, f);
        if (c.variant && _mk(c) === c.type) delete c.variant;
        if (!c.rotation) delete c.rotation;
        return c;
    });
    return JSON.stringify(_canonLayoutValue({
        walls: cfg.walls, floor: cfg.floor, furniture: furniture, branches: cfg.branches,
        canvasWidth: Number(cfg.canvasWidth) || 0, canvasHeight: Number(cfg.canvasHeight) || 0
    }));
}
// True when the office on screen differs from a snapshot (JSON string or object) in anything
// Cancel would restore.
function officeLayoutDiffers(snapshot) {
    if (!snapshot) return false;
    return officeLayoutKey(snapshot) !== officeLayoutKey(officeConfig);
}

function undoEdit() {
    if (_undoStack.length === 0) return;
    var current = JSON.stringify(officeConfig);
    var prev = _undoStack.pop();
    // Skip snapshots identical to what is on screen (nothing to undo there).
    while (prev === current && _undoStack.length) prev = _undoStack.pop();
    if (prev === current) { _updateSaveUndoButtons(); return; }
    _redoStack.push(current);
    applyOfficeConfigSnapshot(prev);
    if (window.OfficeLayouts) {
        window.OfficeLayouts.refreshSelection();
        if (window.OfficeLayouts.notifyUndo) window.OfficeLayouts.notifyUndo();
    }
    saveOfficeConfig();
    _updateSaveUndoButtons();
}

function redoEdit() {
    if (_redoStack.length === 0) return;
    _undoStack.push(JSON.stringify(officeConfig));
    if (_undoStack.length > MAX_UNDO) _undoStack.shift();
    applyOfficeConfigSnapshot(_redoStack.pop());
    if (window.OfficeLayouts) window.OfficeLayouts.refreshSelection();
    saveOfficeConfig();
    _updateSaveUndoButtons();
}

// "Save" now means "save again now" (useful after a failed save).
function saveEdits() {
    return saveOfficeConfig().then(function(ok) {
        _updateSaveUndoButtons();
        return ok;
    });
}

function _updateSaveUndoButtons() {
    var state = (typeof _officeSaveState !== 'undefined' && _officeSaveState) ? _officeSaveState.state : 'idle';
    _hasUnsavedChanges = state === 'saving' || state === 'failed';
    var saveBtn = document.getElementById('btn-save-edits');
    var undoBtn = document.getElementById('btn-undo-edit');
    if (saveBtn) {
        saveBtn.disabled = state !== 'failed';
        saveBtn.style.opacity = state === 'failed' ? '1' : '0.4';
        saveBtn.title = state === 'failed' ? 'Save failed: try again' : 'Changes save automatically';
    }
    if (undoBtn) {
        undoBtn.disabled = _undoStack.length === 0;
        undoBtn.style.opacity = _undoStack.length > 0 ? '1' : '0.4';
        undoBtn.title = 'Undo (Ctrl+Z)';
    }
    var redoBtn = document.getElementById('btn-redo-edit');
    if (redoBtn) {
        redoBtn.disabled = _redoStack.length === 0;
        redoBtn.style.opacity = _redoStack.length > 0 ? '1' : '0.4';
    }
}

// Visible save state in edit mode (Saving / All changes saved / Save failed).
function _renderOfficeSaveStatus() {
    if (typeof document === 'undefined' || !document.body) return;
    var el = document.getElementById('vo-office-save-status');
    if (!el) {
        el = document.createElement('div');
        el.id = 'vo-office-save-status';
        el.className = 'vo-office-save-status';
        el.setAttribute('role', 'status');
        el.setAttribute('aria-live', 'polite');
        // Float over the top of the office canvas so it never crowds a toolbar.
        var host = (canvas && canvas.parentElement) || document.body;
        host.appendChild(el);
    }
    // One compact pill while editing: mode, office size and save state (OE-28).
    var st = _officeSaveState || { state: 'idle' };
    el.hidden = !editMode;
    el.className = 'vo-office-save-status is-' + st.state;
    el.textContent = '';
    function part(cls, text) {
        var span = document.createElement('span');
        span.className = cls;
        span.textContent = text;
        el.appendChild(span);
        return span;
    }
    part('vo-osp-mode', 'Editing');
    part('vo-osp-size', Math.round(W / TILE) + ' × ' + Math.round(H / TILE) + ' tiles');
    if (st.state === 'saving') part('vo-osp-state', 'Saving…');
    else if (st.state === 'saved') part('vo-osp-state', 'All changes saved');
    else if (st.state === 'failed') {
        part('vo-osp-state', 'Not saved. ' + (st.detail || 'Your changes are kept here.'));
        var retry = document.createElement('button');
        retry.type = 'button';
        retry.textContent = 'Retry';
        retry.addEventListener('click', function() { saveEdits(); });
        el.appendChild(retry);
    }
    _updateSaveUndoButtons();
}

// --- WORLD MANIFEST (v0.10.1 world contract W1, review 11-05) -------------------------------
// One entry per furniture type: the single source of truth for where a piece is
// drawn, where it stands on the floor, where people sit, stand and use it and
// where things go on it. Local, UNROTATED coordinates from the item's origin
// (item.x, item.y); _rotXY turns them for 90/180/270 the way the canvas turns
// the art (round the origin, clockwise on screen). The old tables are views
// generated from it: FURNITURE_BOUNDS, SOLID_FURNITURE_TYPES, FURNITURE_ACTIONS,
// DESK_SEAT, DESK_TOP_SPOTS, WALL_ITEM_TYPES, NO_DEPTH_TYPES,
// FLAT_DEPTH_TYPES, DEPTH_ART_RECT, TALL_FURNITURE_TYPES, WALL_MOUNTED_ITEMS,
// COUNTER_ONLY_ITEMS; _depthParts, _meetingSeats, _addCouchSeats,
// _deskMonitorRects, _deskTopRect and the counter rules read it directly.
// A furniture type without an entry fails tests/test_v10_world_contract.mjs.
//   bounds     {w, h, ox, oy[, noCollision]}: the drawn box (selection, hit tests,
//              collision tiles); its top-left is (-ox*w, -oy*h) from the origin.
//   footprint  [[x, y, w, h], ...] floor contact (back edge to the base line):
//              nobody stands or spawns inside (spawn, contract test; W2 enforces).
//   mount      'floor' (default) | 'wall' (the wall plane, everyone in front) |
//              'surface' (stands on a kitchen counter top at z 25, no floor footprint).
//   topWall    'rect' | 'origin': the editor only places it on the top wall.
//   depth      'wall' | 'label' (on top of everything, no sorting) | omitted =
//              a floor piece sorted with people by its parts.
//   parts      depth parts [{name, rect: [x, y, w, h] | 'art', base (from the
//              bottom of baseRect or rect), baseRect?, art0? (rect at rotation 0),
//              seat? (the chair round the seat's hip point)}]; default: the
//              drawn box, base 6 px above its bottom. flat: turned 90/270 a deep
//              part is cut into bands (low pieces whose height is floor depth).
//   seats      [{id, kind, x, y (hip point), facing (at rotation 0), floor (where
//              the walk ends), behind (own parts drawn under the sitter: a piece
//              never covers its sitters), front (drawn over the sitter by the
//              sitter: 'chair' = the chair's front / turned backrest at every turn,
//              'backrest' = the couch back over the hips when the turned seat
//              faces away, 'cut' = the top in front of the hips is left out; a
//              desk turned 180: the chair stands behind the sitter, the desk hides
//              the legs, so nothing is drawn over the body),
//              at: {rot: values that are not a turned copy, as the chair is drawn
//              upright}}]; meeting tables: seatLayout on the turned table top.
//   stand      [{id, x, y (feet), action, faceDir?, extra? (manifest only, not
//              yet a FURNITURE_ACTIONS spot)}]; queue: true = a service queue.
//   surface    {rect: [x, y, w, h], spots: {name: [x, y]}} (desk props, counter top).
//   rotatable  R in the editor; every turn is redrawn with the camera (projection.views).
//   petRest    [x, y] where the office pet lies (pet bed): inside the footprint like a seat's hip point; its walk
//              ends on the stand spot 'pet' (v0.12). Stand spots with pet: true are the pet's (bed, bowl); the
//              editor needs at least one of them where the pet can stand (_petSpotProblem).
// The one rotation helper (any multiple of 90; c/s rounded like the canvas turn):
function _rotXY(x, y, rot) {
    if (!rot) return [x, y];
    var c = Math.round(Math.cos(rot * Math.PI / 180)), s = Math.round(Math.sin(rot * Math.PI / 180));
    return [x * c - y * s, x * s + y * c];
}
