var _FACINGS = ['up', 'right', 'down', 'left'];
function _rotFacing(f, rot) {
    var i = _FACINGS.indexOf(f);
    return i < 0 ? f : _FACINGS[(i + Math.round((rot || 0) / 90) % 4 + 4) % 4];
}
