            if (back) { p(c, -12, -41, 24, 2); p(sh, -2, -41, 4, 2); break; }              // strap and buckle, lenses face front
            p(c, -10, -42, 20, 3); p('#81d4fa', -8, -42, 7, 4); p('#81d4fa', 1, -42, 7, 4);
