    ctx.fillStyle = '#f7f9fa'; ctx.fillRect(x + 2, y + 2, 24, 27);       // board
    ctx.fillStyle = '#e3e8eb'; ctx.fillRect(x + 25, y + 2, 1, 27); ctx.fillRect(x + 2, y + 28, 24, 1);
