        if (row && row.draw) {
            ctx.save(); ctx.translate(item.x, item.y);
            try { row.draw(_variantKit(row.key), rot, _FIN, false); } finally { ctx.restore(); }
        } else if (item.type === 'bossDesk') drawBossDesk(item.x, item.y, false, rot);
        else drawDesk(item.x, item.y, false, rot);
