    K.face = function(rot, plan, z, h) { var t = _projTurn(plan, rot); return [t[0], t[1] + t[3] - z - h, t[2], h]; };
    // An inset panel line (top and left edge, 3 px in) on a face: a side panel's look.
    K.inset = function(f, c) { if (f[2] < 8 || f[3] < 8) return; ctx.fillStyle = col(c); ctx.fillRect(f[0] + 3, f[1] + 3, f[2] - 6, 1); ctx.fillRect(f[0] + 3, f[1] + 3, 1, f[3] - 6); };
    K.keys = function(rot, plan, lift) { var k = _projTurn(plan, rot); _drawKeysAt(k[0], k[1] - lift, k[2], k[3]); };
    K.mouse = function(rot, plan, lift) { var o = _projTurn(plan, rot); _drawMouseAt(o[0], o[1] - lift, o[2], o[3]); };
    K.seat = function(rot) { var g = DESK_SEAT[key]; return g && (g[rot] || g[0]); };
