    ctx.fillStyle = '#62717a'; ctx.fillRect(x - 2, y + 3, 1, 10); ctx.fillRect(x + 2, y + 3, 1, 10); // ribs
    ctx.fillStyle = '#a7b4bb'; _pixelEllipse(x, y + 1, 8, 3);              // rim
    ctx.fillStyle = '#2f383d'; _pixelEllipse(x, y + 1, 6, 2);              // opening
    // v0.12 click reaction: k 0 = the ball in the bin (as before), 1 = on the floor beside it; a small hop in between.
    var rx = _rxCur, k = !rx ? 0 : rx.t >= 0 ? (rx.state === 1 ? rx.t : 1 - rx.t) : rx.state;
