    ctx.fillStyle = '#9e9e9e'; ctx.fillRect(x + 28, y + 12, 2, 6); ctx.fillRect(x + 42, y + 12, 2, 6); // handles
    _camBox(x, y + 4, 72, 24, 23, 2, '#c9c3b6', { front: '#a9a396' });              // worktop
    ctx.fillStyle = 'rgba(255,255,255,0.18)'; ctx.fillRect(x + 3, y - 18, 66, 1);
