// Turned counter (rotation rule): the cabinet's end panel with the toe-kick
// notch on the front side at 90/270, the plain back panel at 180; the worktop
// with its 2 px edge lifted 25 px over the turned plan. Takes no appliances.
function _drawKitchenCounterTurned(x, y, rot) {
    var r = _projTurn([0, 4, 72, 24], rot), X = x + r[0], Y = y + r[1];
    var fy = _camBox(X, Y, r[2], r[3], 0, 23, '#e9e6df', { noTop: true, front: rot === 180 ? '#d9d5cc' : '#e2ded6' });
    if (rot === 180) {                                                                  // back: panel seams
        ctx.fillStyle = '#cbc6bb'; ctx.fillRect(X + 24, fy + 2, 1, 19); ctx.fillRect(X + 48, fy + 2, 1, 19);
    } else {                                                                            // end: toe-kick notch toward the front
        ctx.fillStyle = '#9e998d'; ctx.fillRect(rot === 90 ? X : X + r[2] - 3, fy + 20, 3, 3);
        ctx.fillStyle = '#d6d2c9'; ctx.fillRect(X + 3, fy + 3, r[2] - 6, 1); ctx.fillRect(X + 3, fy + 3, 1, 14);   // inset
    }
    _camBox(X, Y, r[2], r[3], 23, 2, '#c9c3b6', { front: '#a9a396' });                // worktop
    ctx.fillStyle = 'rgba(255,255,255,0.18)'; ctx.fillRect(X + 3, Y - 22, r[2] - 6, 1);
    var f = _projTurn([0, 26, 72, 2], rot), u = _projTurn([0, 4, 72, 3], rot), m = _projTurn([35, 4, 2, 24], rot);
    ctx.fillStyle = '#b3ad9f'; ctx.fillRect(x + f[0], y + f[1] - 25, f[2], f[3]);        // the worktop's front lip
    ctx.fillStyle = '#d8d3c8'; ctx.fillRect(x + u[0], y + u[1] - 25, u[2], u[3]);        // upstand along the back
    ctx.fillStyle = 'rgba(0,0,0,0.06)'; ctx.fillRect(x + m[0], y + m[1] - 25, m[2], m[3]); // joint of the two cabinets
}

