    // v0.12 click reaction: the lever pushes the bread down (state 1: toasting, the slots glow), the next click pops it up.
    var rx = _rxCur, down = !rx ? 0 : rx.t >= 0 ? Math.round((rx.state === 1 ? rx.t : 1 - rx.t) * 3) : rx.state === 1 ? 3 : 0;
    // Bread peeking
    ctx.fillStyle = '#d4a056'; ctx.fillRect(x + 3, y + down, 4, 3 - down);
    ctx.fillRect(x + 10, y + down, 4, 3 - down);
