function drawDartBoard(x, y) {
    // v0.10: crisp pixel board on a tripod; (x, y) = board centre.
    x = Math.round(x); y = Math.round(y);
    ctx.fillStyle = FLOOR_SHADOW; _pixelEllipse(x + 3, y + 51, 18, 3);
    ctx.fillStyle = '#5f6b72';                                            // tripod legs (pixel steps)
    _pixelLine(x - 6, y + 16, x - 17, y + 49, 2); _pixelLine(x + 6, y + 16, x + 17, y + 49, 2); _pixelLine(x, y + 16, x, y + 47, 2);
    ctx.fillStyle = '#3e4a51'; ctx.fillRect(x - 20, y + 48, 5, 3); ctx.fillRect(x + 16, y + 48, 5, 3); ctx.fillRect(x - 2, y + 46, 4, 3);
    ctx.fillStyle = '#4e342e'; ctx.fillRect(x - 17, y - 17, 34, 34);       // backboard
    ctx.fillStyle = '#6d4c41'; ctx.fillRect(x - 16, y - 16, 32, 32);
    ctx.fillStyle = '#8d6e63'; ctx.fillRect(x - 16, y - 16, 32, 1); ctx.fillRect(x - 16, y - 16, 1, 32);
    ctx.fillStyle = '#1e1e1e'; _pixelDisc(x, y, 13);
    ctx.fillStyle = '#b3261e'; _pixelDisc(x, y, 12);                       // double ring
    ctx.fillStyle = '#efe6d2'; _pixelDisc(x, y, 11);
    ctx.fillStyle = '#1e1e1e';                                            // dark wedges
    ctx.fillRect(x - 11, y - 1, 22, 2); ctx.fillRect(x - 1, y - 11, 2, 22);
    for (var d = 2; d < 10; d++) { ctx.fillRect(x + d - 1, y + d - 1, 2, 2); ctx.fillRect(x - d - 1, y + d - 1, 2, 2); ctx.fillRect(x + d - 1, y - d - 1, 2, 2); ctx.fillRect(x - d - 1, y - d - 1, 2, 2); }
    ctx.fillStyle = '#2e7d32'; _pixelDisc(x, y, 7);                        // treble ring
    ctx.fillStyle = '#efe6d2'; _pixelDisc(x, y, 6);
    ctx.fillStyle = '#1e1e1e'; ctx.fillRect(x - 6, y - 1, 12, 2); ctx.fillRect(x - 1, y - 6, 2, 12);
    ctx.fillStyle = '#2e7d32'; ctx.fillRect(x - 2, y - 2, 4, 4);           // outer bull
    ctx.fillStyle = '#c62828'; ctx.fillRect(x - 1, y - 1, 2, 2);           // bullseye
    for (var di = 0; di < dartStuckDarts.length; di++) {
        var dd = dartStuckDarts[di];
        ctx.fillStyle = dd.color; ctx.fillRect(Math.round(x + dd.ox) - 1, Math.round(y + dd.oy) - 1, 3, 3); // tip
        ctx.fillStyle = dd.flightColor; ctx.fillRect(Math.round(x + dd.ox) - 1, Math.round(y + dd.oy) - 4, 3, 3); // flight
    }
    // v0.12 click reaction: your own darts (amber flights), one more per click, the third in the bull.
    var rd = _rxCur ? _rxCur.state : 0, spots = [[-5, 5], [6, -3], [0, 1]];
    for (var ri = 0; ri < rd; ri++) {
        ctx.fillStyle = '#cfd8dc'; ctx.fillRect(x + spots[ri][0] - 1, y + spots[ri][1] - 1, 3, 3);
        ctx.fillStyle = '#ffb300'; ctx.fillRect(x + spots[ri][0] - 1, y + spots[ri][1] - 4, 3, 3);
    }
}
// A crisp w-px line made of rects (no anti-aliased strokes in the art).
function _pixelLine(x0, y0, x1, y1, w) {
    var n = Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0)) || 1;
    for (var i = 0; i <= n; i++) ctx.fillRect(Math.round(x0 + (x1 - x0) * i / n), Math.round(y0 + (y1 - y0) * i / n), w || 1, w || 1);
}

