// --- PING PONG TABLE ---
var PONG_TABLE = { x: 190, y: 105, w: 80, h: 48 };
// The players' feet: PONG_SIDE px from the table's centre (the manifest's stand spots): the body clear of the
// table's ends (body box, review 11-06).
var PONG_SIDE = 60;
function _updatePongTablePos() {
    if (!PONG_TABLE || !officeConfig || !officeConfig.furniture) return;
    for (var i = 0; i < officeConfig.furniture.length; i++) {
        if (officeConfig.furniture[i].type === 'pingPongTable') {
            PONG_TABLE.x = officeConfig.furniture[i].x;
            PONG_TABLE.y = officeConfig.furniture[i].y;
            return;
        }
    }
}
var pongGames = [];

function drawPingPongTable(x, y) {
    // v0.10: a bigger table (92 wide) with a top face, apron, legs, net posts
    // and a resting paddle + ball. (x, y) = centre of the table's plan. VO 3/4
    // camera: plan y -20..24 lifted 21 px = top face y -41..3, apron 5 + legs 16
    // down to the base line y 24; the net = a 4 px upright strip down the middle.
    x = Math.round(x); y = Math.round(y);
    var T = y - 41;                                                       // top face back edge
    ctx.fillStyle = '#3e4a51';
    ctx.fillRect(x - 44, y + 8, 3, 16); ctx.fillRect(x + 41, y + 8, 3, 16); ctx.fillRect(x - 2, y + 8, 3, 15); // legs
    _camBox(x - 46, y - 20, 92, 44, 16, 5, '#2e6b40', { front: '#1f5130' }); // top + apron
    ctx.fillStyle = '#367a4a'; ctx.fillRect(x - 45, T + 1, 44, 42);      // lit half
    ctx.fillStyle = '#f2f2ec';                                            // white lines
    ctx.fillRect(x - 45, T + 1, 90, 1); ctx.fillRect(x - 45, T + 42, 90, 1);
    ctx.fillRect(x - 45, T + 1, 1, 42); ctx.fillRect(x + 44, T + 1, 1, 42);
    ctx.fillStyle = 'rgba(242,242,236,0.6)'; ctx.fillRect(x - 45, T + 21, 90, 1);
    ctx.fillStyle = 'rgba(0,0,0,0.16)'; ctx.fillRect(x + 2, T, 2, 44);   // the net's shadow on the top
    ctx.fillStyle = '#e6e6e0'; ctx.fillRect(x - 1, T - 4, 3, 48);        // net: 4 px up from the top, back to front
    ctx.fillStyle = '#b0b8bc';
    for (var ny = -3; ny < 44; ny += 3) ctx.fillRect(x, T + ny, 1, 1);
    ctx.fillStyle = '#fafaf6'; ctx.fillRect(x - 1, T - 4, 3, 1);
    ctx.fillStyle = '#5f6b72'; ctx.fillRect(x - 2, T - 5, 5, 3); ctx.fillRect(x - 2, T + 42, 5, 4); // posts (clamps)
    // Resting paddle and ball (the game draws its own while people play)
    ctx.fillStyle = '#8d6e63'; ctx.fillRect(x + 30, T + 33, 5, 2);
    ctx.fillStyle = '#c62828'; _pixelEllipse(x + 26, T + 34, 5, 4);
    ctx.fillStyle = '#e57373'; ctx.fillRect(x + 23, T + 31, 3, 1);
    ctx.fillStyle = '#ffffff'; ctx.fillRect(x - 30, T + 31, 3, 3);
    ctx.fillStyle = '#d9d9d2'; ctx.fillRect(x - 28, T + 33, 1, 1);
}

// opts (Office life tournaments): a decided result, see _lifeGamePlan.
function startPongGame(a1, a2, opts) {
    var g = {
        p1: a1, p2: a2,
        ballX: 0, ballY: 0, ballVX: 1.5, ballVY: 0.8,
        p1Score: 0, p2Score: 0,
        p1Y: 0, p2Y: 0,
        phase: 'walking', // walking → playing → result
        timer: 0, maxRounds: 5
    };
    if (opts) {
        // The ball still flies; who misses follows the planned points.
        var plan = _lifeGamePlan(a1, a2, opts, 3);
        g.forced = opts; g.plan = plan.points; g.maxRounds = plan.points.length;
        g.rally = 0;
        g.rallyLen = Math.max(1, Math.min(8, Math.round(((opts.ms || 40000) * 0.06 - 240) / plan.points.length / 45) - 1));
    }
    a1.idleAction = 'pong'; a1.interactTimer = 0; a1.idleReturnTimer = 0;
    a2.idleAction = 'pong'; a2.interactTimer = 0; a2.idleReturnTimer = 0;
    // Walk to table sides
    a1.targetX = PONG_TABLE.x - PONG_SIDE; a1.targetY = PONG_TABLE.y;
    a2.targetX = PONG_TABLE.x + PONG_SIDE; a2.targetY = PONG_TABLE.y;
    pongGames.push(g);
}

function _hasPongTable() {
    return !!(officeConfig && officeConfig.furniture && officeConfig.furniture.some(function(f) { return f.type === 'pingPongTable'; }));
}

// End any minigame an agent is part of (pong, darts) and send the partner back
// to their desk. Called whenever real work or a meeting moves the agent (CV-21).
// reason: what a decided (Office life) game's onAbort hears; default 'moved'.
function endGamesForAgent(agentId, reason) {
    for (var i = pongGames.length - 1; i >= 0; i--) {
        var g = pongGames[i];
        if (g.p1.id !== agentId && g.p2.id !== agentId) continue;
        pongGames.splice(i, 1);
        if (g.forced) { g.p1.idleAction = null; g.p2.idleAction = null; _lifeGameAbort(g, reason || 'moved', agentId); continue; }
        [g.p1, g.p2].forEach(function(a) {
            if (a.id === agentId) return;
            a.idleAction = null;
            a.targetX = a.desk.x; a.targetY = a.desk.y;
        });
    }
    for (var j = dartGames.length - 1; j >= 0; j--) {
        var d = dartGames[j];
        if (d.p1 !== agentId && d.p2 !== agentId) continue;
        dartGames.splice(j, 1);
        dartStuckDarts = [];
        if (d.forced) {
            [d.p1, d.p2].forEach(function(id) { if (agentMap[id]) agentMap[id].idleAction = null; });
            _lifeGameAbort(d, reason || 'moved', agentId);
            continue;
        }
        [d.p1, d.p2].forEach(function(id) {
            var other = agentMap[id];
            if (!other || id === agentId) return;
            other.idleAction = null;
            other.returnToDesk();
        });
    }
}

// --- Office life: games with a decided result (tournaments, v0.9) ---
// opts.score is [p1, p2], 'a-b' (p1 first) or {p1, p2}; opts.winner is the
// winner's key. Points (pong) or rounds (darts) are planned so the shown
// result always matches the server's; the ball and darts stay visual.
function _lifeGamePlan(a1, a2, opts, target) {
    var sc = opts.score, s1 = NaN, s2 = NaN, m;
    if (Array.isArray(sc)) { s1 = Number(sc[0]); s2 = Number(sc[1]); }
    else if (typeof sc === 'string' && (m = sc.match(/^\s*(\d+)\s*[-:]\s*(\d+)\s*$/))) { s1 = Number(m[1]); s2 = Number(m[2]); }
    else if (sc && typeof sc === 'object') { s1 = Number(sc.p1); s2 = Number(sc.p2); }
    var wk = opts.winner;
    var w = (wk != null && (wk === a2.statusKey || wk === a2.id)) ? 'p2'
        : (wk != null && (wk === a1.statusKey || wk === a1.id)) ? 'p1' : (s2 > s1 ? 'p2' : 'p1');
    var ws = w === 'p1' ? s1 : s2, ls = w === 'p1' ? s2 : s1;
    if (!(ws >= 1)) ws = target;
    if (!(ls >= 0)) ls = 0;
    ws = Math.min(Math.round(ws), 11);
    ls = Math.min(Math.round(ls), ws - 1);
    var l = w === 'p1' ? 'p2' : 'p1', points = [], wl = ws - 1, ll = ls, turn = 0;
    while (wl > 0 || ll > 0) {
        if ((turn % 2 === 0 && wl > 0) || ll === 0) { points.push(w); wl--; } else { points.push(l); ll--; }
        turn++;
    }
    points.push(w); // the winner always takes the last point
    return { winner: w, points: points };
}
function _lifeGameEnd(g, winner, s1, s2) {
    if (g._lifeDone) return;
    g._lifeDone = true;
    var o = g.forced;
    if (o && typeof o.onEnd === 'function') {
        try { o.onEnd({ winner: winner && (winner.statusKey || winner.id), p1Score: s1, p2Score: s2 }); } catch (e) {}
    }
}
function _lifeGameAbort(g, reason, key) {
    if (g._lifeDone) return;
    g._lifeDone = true;
    var o = g.forced;
    if (o && typeof o.onAbort === 'function') {
        var a = key && agentMap[key];
        try { o.onAbort(reason, a ? a.statusKey : key); } catch (e) {}
    }
}
function _lifeStartGame(kind, aKey, bKey, opts) {
    var a = _findOfficeAgent(aKey), b = _findOfficeAgent(bKey);
    if (!a || !b || a === b) return false;
    opts = opts || {};
    if (kind === 'pong') {
        if (!_hasPongTable()) return false;
        // The table is booked: a game already there ends, its players go back.
        pongGames.splice(0).forEach(function(g) {
            if (g.forced) { _lifeGameAbort(g, 'replaced', null); return; }
            [g.p1, g.p2].forEach(function(p) { p.idleAction = null; p.targetX = p.desk.x; p.targetY = p.desk.y; });
        });
        startPongGame(a, b, opts);
    } else {
        if (!_lifeItems('dartBoard').length || !(LOCATIONS.interactions && LOCATIONS.interactions.dartBoard)) return false;
        dartGames.splice(0).forEach(function(g) {
            if (g.forced) { _lifeGameAbort(g, 'replaced', null); return; }
            [g.p1, g.p2].forEach(function(id) { var p = agentMap[id]; if (p) { p.idleAction = null; p.returnToDesk(); } });
        });
        dartStuckDarts = [];
        if (startDartGame(a, b, opts) === false) return false;
    }
    _markSceneDirty();
    return true;
}

function maybeStartPong(agent) {
    if (agent.idleAction === 'pong' || pongGames.length >= 1) return;
    if (!_hasPongTable()) return;
    // Agent waiting at table — look for a partner already there
    if (agent.idleAction === 'pong_wait') {
        // Check if arrived at table first
        var distToTable = Math.abs(agent.x - PONG_TABLE.x) + Math.abs(agent.y - PONG_TABLE.y);
        if (distToTable > 80) return; // still walking
        for (var i = 0; i < agents.length; i++) {
            var other = agents[i];
            if (other.id === agent.id) continue;
            if (other.idleAction === 'pong_wait') {
                var otherDist = Math.abs(other.x - PONG_TABLE.x) + Math.abs(other.y - PONG_TABLE.y);
                if (otherDist < 80) { startPongGame(agent, other); return; }
            }
        }
        // Active recruitment — pull ONE random idle agent to come play (only if < 2 waiting)
        var _waitCount = agents.filter(function(a) { return a.idleAction === 'pong_wait'; }).length;
        if (_waitCount < 2 && Math.random() < 0.02) {
            var candidates = [];
            for (var j = 0; j < agents.length; j++) {
                var c = agents[j];
                if (c.id === agent.id) continue;
                if (c.state === 'idle' && !c.idleAction && !c.meetingId && c.isSitting && !c._lifeHold) candidates.push(c);
            }
            if (candidates.length > 0) {
                var recruit = candidates[Math.floor(Math.random() * candidates.length)];
                var _rw = _worldNear(PONG_TABLE.x + (agent.x < PONG_TABLE.x ? PONG_SIDE : -PONG_SIDE), PONG_TABLE.y, 0, 5);
                recruit.targetX = _rw.x;
                recruit.targetY = _rw.y;
                recruit.idleAction = 'pong_wait';
                recruit.idleReturnTimer = 1800 + Math.floor(Math.random() * 1200);
                recruit.isSitting = false;
                recruit.addIntent('Heading to play ping pong');
            }
        }
        return;
    }
    // Social trigger — two agents near each other anywhere
    if (agent.socialTarget && agent.id < agent.socialTarget && Math.random() < 0.005) {
        var other = agentMap[agent.socialTarget];
        if (other && !other.isSitting && !other.idleAction && !agent.idleAction && agent.state === 'idle' && other.state === 'idle') {
            startPongGame(agent, other);
        }
    }
}

function updatePongGames() {
    _updatePongTablePos();
    for (var i = pongGames.length - 1; i >= 0; i--) {
        var g = pongGames[i];
        var p1 = g.p1, p2 = g.p2;
        g.timer++;

        if (g.phase === 'walking') {
            var d1 = Math.abs(p1.x - (PONG_TABLE.x - PONG_SIDE)) + Math.abs(p1.y - PONG_TABLE.y);
            var d2 = Math.abs(p2.x - (PONG_TABLE.x + PONG_SIDE)) + Math.abs(p2.y - PONG_TABLE.y);
            if (g.forced && g.timer > 480 && !(d1 < 5 && d2 < 5)) {
                // A decided game never waits on a blocked walk: both step to their side.
                [[p1, -PONG_SIDE], [p2, PONG_SIDE]].forEach(function(s) {
                    s[0].x = s[0].targetX = s[0]._prevTargetX = PONG_TABLE.x + s[1];
                    s[0].y = s[0].targetY = s[0]._prevTargetY = PONG_TABLE.y;
                    s[0]._path = null;
                });
                d1 = d2 = 0;
            }
            if (d1 < 5 && d2 < 5) {
                g.phase = 'playing'; g.timer = 0;
                p1.faceDir = 1; p2.faceDir = -1;
                g.ballX = 0; g.ballY = 0;
                g.p1Y = 0; g.p2Y = 0;
            }
            if (g.timer > (g.forced ? 2700 : 300)) {
                pongGames.splice(i, 1); p1.idleAction = null; p2.idleAction = null;
                if (g.forced) _lifeGameAbort(g, 'timeout', null);
                continue;
            }
        }

        if (g.phase === 'playing') {
            // Ball physics
            g.ballX += g.ballVX;
            g.ballY += g.ballVY;
            // Bounce off top/bottom
            if (g.ballY > 18 || g.ballY < -18) g.ballVY *= -1;
            // Paddle AI — with reaction delay and imperfection
            if (!g.p1Offset) g.p1Offset = 0;
            if (!g.p2Offset) g.p2Offset = 0;
            // Randomize target slightly so they don't perfectly track
            if (g.timer % 30 === 0) {
                g.p1Offset = (Math.random() - 0.5) * 12;
                g.p2Offset = (Math.random() - 0.5) * 12;
            }
            // A decided game: the planned point loser drifts off once the rally is long enough.
            var _sc = g.forced ? (g.plan[g.p1Score + g.p2Score] || 'p1') : null;
            var _missOk = g.forced && g.rally >= g.rallyLen;
            if (g.forced) {
                g.p1Offset = (_sc === 'p2' && _missOk) ? 16 : 0;
                g.p2Offset = (_sc === 'p1' && _missOk) ? 16 : 0;
            }
            // Only track when ball is on their side
            if (g.ballVX < 0) {
                g.p1Y += (g.ballY + g.p1Offset - g.p1Y) * 0.12;
            } else {
                g.p1Y += (0 - g.p1Y) * 0.03; // drift back to center
            }
            if (g.ballVX > 0) {
                g.p2Y += (g.ballY + g.p2Offset - g.p2Y) * 0.10;
            } else {
                g.p2Y += (0 - g.p2Y) * 0.03;
            }
            // Lock agents to table sides + track ball vertically
            p1.x = PONG_TABLE.x - PONG_SIDE;
            p2.x = PONG_TABLE.x + PONG_SIDE;
            p1.y = PONG_TABLE.y + g.p1Y * 0.6;
            p2.y = PONG_TABLE.y + g.p2Y * 0.6;
            // Sync targets so isMoving stays false (paddles render)
            p1.targetX = p1.x; p1.targetY = p1.y;
            p2.targetX = p2.x; p2.targetY = p2.y;
            // Keep facing the table
            p1.faceDir = 1; p2.faceDir = -1;
            // Swing tracking — how close ball is to each paddle
            g.p1Swing = g.ballX < -20 ? Math.min(1, (-20 - g.ballX) / 16) : 0;
            g.p2Swing = g.ballX > 20 ? Math.min(1, (g.ballX - 20) / 16) : 0;
            // Score — ball past paddles
            if (g.ballX > 36) {
                g.p1Score++; g.ballX = 0; g.ballY = 0; g.rally = 0;
                g.ballVX = -1.5; g.ballVY = (Math.random() - 0.5) * 2;
            }
            if (g.ballX < -36) {
                g.p2Score++; g.ballX = 0; g.ballY = 0; g.rally = 0;
                g.ballVX = 1.5; g.ballVY = (Math.random() - 0.5) * 2;
            }
            // Paddle hit — with angle variation (a decided game returns every ball
            // except the planned miss)
            var _p1Hit = g.forced ? !(_sc === 'p2' && _missOk) : Math.abs(g.ballY - g.p1Y) < 8;
            var _p2Hit = g.forced ? !(_sc === 'p1' && _missOk) : Math.abs(g.ballY - g.p2Y) < 8;
            if (g.ballX < -30 && g.ballVX < 0 && _p1Hit) {
                g.ballVX = Math.abs(g.ballVX) * (1.02 + Math.random() * 0.1);
                g.ballVY = (g.ballY - g.p1Y) * 0.4 + (Math.random() - 0.5) * 1.5;
                if (g.forced) g.rally++;
            }
            if (g.ballX > 30 && g.ballVX > 0 && _p2Hit) {
                g.ballVX = -Math.abs(g.ballVX) * (1.02 + Math.random() * 0.1);
                g.ballVY = (g.ballY - g.p2Y) * 0.4 + (Math.random() - 0.5) * 1.5;
                if (g.forced) g.rally++;
            }
            // Speed cap
            g.ballVX = Math.max(-3, Math.min(3, g.ballVX));
            g.ballVY = Math.max(-2, Math.min(2, g.ballVY));

            // End after maxRounds total points
            if (g.p1Score + g.p2Score >= g.maxRounds) {
                g.phase = 'result'; g.timer = 0;
            }
        }

        if (g.phase === 'result') {
            if (g.timer > 120) {
                // Winner celebrates
                var winner = g.p1Score > g.p2Score ? p1 : p2;
                winner._socialMouth = 'laugh';
                p1.idleAction = null; p2.idleAction = null;
                pongGames.splice(i, 1);
                if (g.forced) { _lifeGameEnd(g, winner, g.p1Score, g.p2Score); continue; }
                p1.targetX = p1.desk.x; p1.targetY = p1.desk.y;
                p2.targetX = p2.desk.x; p2.targetY = p2.desk.y;
            }
        }
    }
}

function drawPongGames() {
    for (var i = 0; i < pongGames.length; i++) {
        var g = pongGames[i];
        if (g.phase !== 'playing' && g.phase !== 'result') continue;
        var tx = PONG_TABLE.x, ty = PONG_TABLE.y - 19;   // the middle of the raised top face (VO 3/4 camera)

        // Ball (small white circle)
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(tx + g.ballX, ty + g.ballY, 2, 0, Math.PI * 2); ctx.fill();

        // Paddles removed — rackets are drawn on agents now

        // Scoreboard (names stacked to avoid overlap)
        ctx.fillStyle = 'rgba(0,0,0,0.6)';
        ctx.fillRect(tx - 30, ty - 42, 60, 20);
        _drawPixelText(g.p1.name + ': ' + g.p1Score, tx, ty - 39, '#ef9a9a', 1, 'center');
        _drawPixelText(g.p2.name + ': ' + g.p2Score, tx, ty - 30, '#90caf9', 1, 'center');

        // Result
        if (g.phase === 'result') {
            var winnerName = g.p1Score > g.p2Score ? g.p1.name : g.p2.name;
            ctx.fillStyle = 'rgba(0,0,0,0.7)';
            ctx.fillRect(tx - 30, ty - 10, 60, 16);
            _drawPixelText(winnerName + ' WINS!', tx, ty - 4, '#ffd600', 1, 'center');
        }
    }
}

