// Human name for a provider kind (DL-10). Unknown kinds (extensions) use the
// provider's own display name from the roster, else a title-cased kind;
// they are never mislabelled as OpenClaw.
var PROVIDER_KIND_LABELS = {
    'openclaw': 'OpenClaw', 'hermes': 'Hermes', 'codex': 'Codex CLI', 'claude-code': 'Claude Code',
    'opencode': 'OpenCode', 'antigravity': 'Antigravity', 'acp': 'ACP', 'builtin': 'Built-in', 'built-in': 'Built-in'
};
function _providerKindDisplay(providerKind, agent) {
    var kind = String(providerKind || 'openclaw').toLowerCase();
    if (PROVIDER_KIND_LABELS[kind]) return PROVIDER_KIND_LABELS[kind];
    var named = agent && (agent.providerName || agent.providerLabel || agent.provider);
    if (named && String(named).toLowerCase() !== kind) return String(named);
    return kind.replace(/[-_]+/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); });
}

// Dialog subtitle: role, then the provider named once (P3-3). A Hermes agent
// whose role is "Hermes Agent" and transport "Hermes API" reads
// "Hermes Agent · profile: research", not three Hermes mentions.
function _agentSubtitle(agent) {
    agent = agent || {};
    var provider = _providerKindDisplay(agent.providerKind, agent);
    var kind = String(agent.providerKind || 'openclaw').toLowerCase().replace(/[-_]+/g, ' ');
    var role = String(agent.role || '').trim();
    var words = [provider.toLowerCase().split(/\s+/)[0], kind.split(/\s+/)[0]];
    function mentionsProvider(text) {
        text = String(text || '').toLowerCase();
        return words.some(function(w) { return w && text.indexOf(w) >= 0; });
    }
    var bits = [];
    if (role) bits.push(role);
    if (!mentionsProvider(role)) bits.push(provider + ' Agent');
    if (agent.providerAgentId) bits.push('profile: ' + agent.providerAgentId);
    if (agent.provider && !mentionsProvider(agent.provider) && bits.indexOf(agent.provider) < 0) bits.push(agent.provider);
    return bits.join(' · ');
}

// N7: who really sent a "user" turn. Scheduled jobs (OpenClaw "[cron:id name] ...", the
// Hermes cron hint), subagent tasks and heartbeats arrive as user turns carrying an injected
// system prompt: name the source and keep a short summary of the real request instead.
var _REQ_STAMP = /^\s*\[(?:mon|tue|wed|thu|fri|sat|sun)[a-z]*\s[^\]\n]{4,40}\]\s*/i;
