// ============================================================
// PET SPECIES (v0.12): the one list of species. The editor's Pet tab and
// every check read it; PET_ART holds the art of each id. trick = the name of
// the species' own trick (its 'trick' pose); move = how it plays: 'leap'
// (frame 0 is the crouch, frame 1 is lifted lift px in an arc) or 'pose'
// (the frames take turns where it stands).
// ============================================================
var PET_SPECIES = [
    { id: 'cat', label: 'Cat', trick: 'Pounce', move: 'leap', lift: 7 },
    { id: 'pug', label: 'Pug', trick: 'Roll over', move: 'pose' },
    { id: 'lobster', label: 'Lobster', trick: 'Claw snap', move: 'pose' },
    { id: 'corgi', label: 'Corgi', trick: 'Sploot', move: 'pose' },
    { id: 'bunny', label: 'Bunny', trick: 'Binky', move: 'leap', lift: 8 },
    { id: 'fox', label: 'Fox', trick: 'Mouse dive', move: 'leap', lift: 9 },
    { id: 'duck', label: 'Duck', trick: 'Wing flap', move: 'pose' },
    { id: 'turtle', label: 'Turtle', trick: 'Shell hide', move: 'pose' }
];
function _petSpeciesInfo(id) {
    for (var i = 0; i < PET_SPECIES.length; i++) if (PET_SPECIES[i].id === id) return PET_SPECIES[i];
    return null;
}
// Tricks every pet knows: its own ('species'), a double hop, a spin. A click
// or tap plays the next one in this order; now and then it plays one alone.
var PET_TRICK_KINDS = ['species', 'hop', 'spin'];
var PET_TRICK_TICKS = 72;
// The pet's resting states (it stands still in them): none may start inside a clearance band (v0.12 polish).
var PET_RESTING = { sitting: 1, sleeping: 1, grooming: 1, looking_around: 1, trick: 1, eating: 1, being_pet: 1 };
// Reduced motion or Office Life Calm: a trick is one still pose with a star.
function _petStill() {
    if (_lifeReducedMotion()) return true;
    try { return !!(window.VOLife && typeof window.VOLife.calm === 'function' && window.VOLife.calm()); } catch (e) { return false; }
}
// The pet under a click (its drawn body box, grown to min CSS px for touch).
function _petAtWorld(x, y, minCssPx) {
    if (_stackTurned()) return _stackEntityAt(officePets, x, y, minCssPx, 10);
    for (var i = officePets.length - 1; i >= 0; i--) if (_rectHit(officePets[i]._bodyBox, x, y, minCssPx)) return officePets[i];
    return null;
}
function _petClick(x, y, minCssPx) {
    var pet = _petAtWorld(x, y, minCssPx);
    if (!pet) return false;
    pet.startTrick(); // a hit is always taken, even while a trick plays or it runs from a chase
    _markSceneDirty();
    return true;
}

