        if (this._trick === 'hop') return Math.round(5 * Math.abs(Math.sin(Math.PI * Math.min(t, 60) / 30)));
        if (this._trick !== 'species') return 0;
        var info = _petSpeciesInfo(PET_ART[this.species] ? this.species : 'lobster');
