// ============================================================
// EDIT MODE — Canvas expansion/shrink with grid overlay
// ============================================================

const EDIT_BTN_SIZE = 30;
const EDIT_BTN_MARGIN = 8;
const EDIT_RESIZE_HANDLE_LENGTH = 96;
