    var px = 1 / Math.max(0.01, getBaseScale() * camera.zoom);
    var xs = [r.x, r.x + r.w / 2, r.x + r.w], ys = [r.y, r.y + r.h / 2, r.y + r.h];
    var vx = [null, null, null], hy = [null, null, null];
