// ============================================================
// MAIN MENU
// ============================================================
var _mainMenuOpen = false;

function toggleMainMenu() {
    var panel = document.getElementById('main-menu-panel');
    if (!panel) return;
    _mainMenuOpen = !_mainMenuOpen;
    panel.classList.toggle('open', _mainMenuOpen);
    var btn = document.getElementById('btn-main-menu');
    if (btn) btn.classList.toggle('active-edit', _mainMenuOpen);
    if (_mainMenuOpen) _mmLoadCurrentSettings();
}

// Settings form safety (CH-11): Save is only possible after the current
// settings loaded, and only the sections the user changed are sent, so a
// failed load can never wipe Hermes connections, keys, names or URLs.
var _mmSettingsLoaded = false;
var _mmBaseline = null;

function _mmSetSaveState(enabled, message, isError) {
    var btn = document.querySelector('.mm-save-all');
    if (btn) {
        btn.disabled = !enabled;
        btn.setAttribute('aria-disabled', enabled ? 'false' : 'true');
    }
    var status = document.getElementById('mm-save-status');
    if (!status && btn && btn.parentNode) {
        status = document.createElement('div');
        status.id = 'mm-save-status';
        status.className = 'mm-save-status';
        status.setAttribute('role', 'status');
        status.setAttribute('aria-live', 'polite');
        btn.parentNode.insertBefore(status, btn.nextSibling);
    }
    if (!status) return;
    status.innerHTML = '';
    status.classList.toggle('is-error', !!isError);
    if (!message) return;
    var text = document.createElement('span');
    text.textContent = message;
    status.appendChild(text);
    if (isError) {
        var retry = document.createElement('button');
        retry.type = 'button';
        retry.className = 'mm-btn';
        retry.textContent = 'Retry';
        retry.addEventListener('click', function() { _mmLoadCurrentSettings(); });
        status.appendChild(retry);
    }
}

function _mmValue(id) {
    var el = document.getElementById(id);
    if (!el) return null;
    return el.type === 'checkbox' ? !!el.checked : String(el.value == null ? '' : el.value);
}

// Every server-side settings section with a signature of its form values.
function _mmCollectSections() {
    var hermes = document.getElementById('mm-hermes-enable') ? _mmHermesPayload().hermes : null;
    var sections = {
        hermes: hermes,
        office: [_mmValue('mm-office-name'), _mmValue('mm-preview-display'), _mmValue('mm-preview-size'), _mmValue('mm-preview-zoom')],
        weather: [_mmValue('mm-weather-city'), _mmValue('mm-weather-state')],
        pcMetrics: [_mmValue('mm-pcmetrics-enable'), _mmValue('mm-pcmetrics-url')],
        apiUsage: [_mmValue('mm-apiusage-enable')],
        updates: [_mmValue('mm-update-check')],
        browser: [_mmValue('mm-browser-enable'), _mmValue('mm-cdp-url'), _mmValue('mm-viewer-url')]
    };
    var sigs = {};
    Object.keys(sections).forEach(function(key) { sigs[key] = JSON.stringify(sections[key]); });
    return sigs;
}

function _mmLoadCurrentSettings() {
    _mmSettingsLoaded = false;
    _mmBaseline = null;
    _mmSetSaveState(false, 'Loading current settings…', false);
    _mmLoadProviderSummary();
    // Populate fields from current server config
    fetch('/vo-config', { cache: 'no-store' }).then(function(r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
    }).then(function(cfg) {
        if (!cfg || typeof cfg !== 'object' || cfg.error) throw new Error((cfg && cfg.error) || 'empty settings');
        var nameInput = document.getElementById('mm-office-name');
        var weatherCityInput = document.getElementById('mm-weather-city');
        var weatherStateInput = document.getElementById('mm-weather-state');
        var hermesCb = document.getElementById('mm-hermes-enable');
        var hermesFields = document.getElementById('mm-hermes-fields');
        var hermesPlatformEnable = document.getElementById('mm-hermes-platform-enable');
        var hermesPlatformToken = document.getElementById('mm-hermes-platform-token');
        var hermesPlatformAgent = document.getElementById('mm-hermes-platform-agent');
        if (nameInput) nameInput.value = (cfg.office || {}).name || '';
        // Parse "City,State" or "City+Name,State" back into separate fields
        var _wloc = (cfg.weather || {}).location || '';
        var _wparts = _wloc.split(',');
        if (weatherCityInput) weatherCityInput.value = (_wparts[0] || '').replace(/\+/g, ' ');
        if (weatherStateInput) weatherStateInput.value = (_wparts[1] || '').replace(/\+/g, ' ');
        var hermesCfg = cfg.hermes || {};
        var hermesEnabled = hermesCfg.enabled !== false;
        if (hermesCb) hermesCb.checked = hermesEnabled;
        if (hermesFields) hermesFields.style.display = hermesEnabled ? 'block' : 'none';
        if (hermesPlatformEnable) hermesPlatformEnable.checked = !!hermesCfg.platformEnabled;
        if (hermesPlatformToken && hermesCfg.platformTokenConfigured) hermesPlatformToken.placeholder = 'Configured - leave blank to keep';
        if (hermesPlatformAgent) hermesPlatformAgent.value = hermesCfg.platformAgentId || 'hermes-gateway';
        // PC Metrics
        var pcmEnabled = ((cfg.features || {}).pcMetrics) || false;
        var pcmUrl = ((cfg.pcMetrics || {}).url) || "";
        var pcmCb = document.getElementById("mm-pcmetrics-enable");
        var pcmUrlEl = document.getElementById("mm-pcmetrics-url");
        var pcmFields = document.getElementById("mm-pcmetrics-fields");
        if (pcmCb) pcmCb.checked = pcmEnabled;
        if (pcmUrlEl) pcmUrlEl.value = pcmUrl;
        if (pcmFields) pcmFields.style.display = pcmEnabled ? "block" : "none";
        // API Usage
        var apiUsageCb = document.getElementById("mm-apiusage-enable");
        if (apiUsageCb) apiUsageCb.checked = (cfg.features || {}).apiUsage !== false;
        // Version: "Tell me when a new version is out" (vo-updates.js shows the rest of the block)
        var updateCb = document.getElementById('mm-update-check');
        if (updateCb) updateCb.checked = (cfg.features || {}).updateCheck !== false;
        // Browser
        var brEnabled = ((cfg.features || {}).browserPanel) || false;
        var brCdp = ((cfg.browser || {}).cdpUrl) || "";
        var brViewer = ((cfg.browser || {}).viewerUrl) || "";
        var brCb = document.getElementById("mm-browser-enable");
        var brCdpEl = document.getElementById("mm-cdp-url");
        var brViewerEl = document.getElementById("mm-viewer-url");
        var brFields = document.getElementById("mm-browser-fields");
        if (brCb) brCb.checked = brEnabled;
        if (brCdpEl) brCdpEl.value = brCdp;
        if (brViewerEl) brViewerEl.value = brViewer;
        if (brFields) brFields.style.display = brEnabled ? "block" : "none";
        // Live Preview Bubbles
        var previewCfg = ((cfg.office || {}).previewBubbles) || {};
        var previewDisplay = document.getElementById('mm-preview-display');
        var previewSize = document.getElementById('mm-preview-size');
        var previewZoom = document.getElementById('mm-preview-zoom');
        var previewZoomValue = document.getElementById('mm-preview-zoom-value');
        if (previewDisplay) previewDisplay.value = previewCfg.displayMode === 'world' ? 'world' : 'consistent';
        if (previewSize) previewSize.value = ['small', 'medium', 'large'].indexOf(previewCfg.size) >= 0 ? previewCfg.size : 'large';
        var normalizedZoom = Math.max(50, Math.min(200, Math.round((Number(previewCfg.contentZoom) || 100) / 10) * 10));
        if (previewZoom) previewZoom.value = normalizedZoom;
        if (previewZoomValue) previewZoomValue.value = normalizedZoom + '%';
        _mmBaseline = _mmCollectSections();
        _mmSettingsLoaded = true;
        _mmSetSaveState(true, '', false);
    }).catch(function(e) {
        _mmSettingsLoaded = false;
        _mmSetSaveState(false, 'Could not load the current settings (' + ((e && e.message) || 'network error') + '). Saving is off so nothing gets overwritten.', true);
    });
    // Load display prefs from localStorage
    var prefs = {};
    try { prefs = JSON.parse(localStorage.getItem('vo-display-prefs') || '{}'); } catch(e){}
    var cb1 = document.getElementById('mm-show-bubbles');
    var cb2 = document.getElementById('mm-show-weather');
    var cb3 = document.getElementById('mm-show-names');
    if (cb1) cb1.checked = prefs.showBubbles !== false;
    if (cb2) cb2.checked = prefs.showWeather !== false;
    if (cb3) cb3.checked = prefs.showNames !== false;
    var fitSel = document.getElementById('mm-office-fit');
    if (fitSel) fitSel.value = prefs.officeFit === 'fill' ? 'fill' : 'sharp';
    var nightSel = document.getElementById('mm-night-look');
    if (nightSel) nightSel.value = prefs.nightLook === 'dim' ? 'dim' : 'lit';
    _mmGraphicsSync();
}
// Settings > Display > Graphics (stack/stack-loader.js, window.VOGraphics): the
